_PARSE = re.compile(r"(?:([0-9]+)h)?(?:([0-9]+)m)?(?:([0-9]+)s)?")


def parse_duration(s):
    """Total seconds for a string like "1h30m", "45s" or "2h5s". Units h, m, s, in that order, each at most once."""
    m = _PARSE.fullmatch(s)
    if not s or m is None:
        raise ValueError(f"invalid duration: {s!r}")
    hours, minutes, seconds = (int(g) if g is not None else 0 for g in m.groups())
    return hours * 3600 + minutes * 60 + seconds


def format_duration(seconds):
    """Canonical form: hours, then minutes, then seconds, omitting zero parts. 0 -> "0s"."""
    if seconds < 0:
        raise ValueError(f"duration must not be negative: {seconds}")
    hours, rest = divmod(seconds, 3600)
    minutes, secs = divmod(rest, 60)
    parts = []
    if hours:
        parts.append(f"{hours}h")
    if minutes:
        parts.append(f"{minutes}m")
    if secs or not parts:
        parts.append(f"{secs}s")
    return "".join(parts)

